// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes32 roleIndex, address actor) public {
        // pick one of the three managed roles based on fuzzed index
        bytes32 role;
        uint256 sel = bound(uint256(roleIndex) % 3, 0, 2);
        if (sel == 0) role = c.TIMELOCK_ADMIN_ROLE();
        else if (sel == 1) role = c.PROPOSER_ROLE();
        else role = c.EXECUTOR_ROLE();

        // the test contract is the deployer and holds TIMELOCK_ADMIN_ROLE,
        // which administers all three roles, so it may grant any of them
        vm.prank(address(this));
        c.grantRole(role, actor);

        // general rule: a granted role is reported by hasRole for ANY account
        assertTrue(c.hasRole(role, actor));
    }
}
